-- Native development schema version 2. The PHP relations/indexes below are
-- captured from the image pinned in tests/Fixtures/ServerParity/php-baseline.json.
-- This creates a fresh database; it never converts or adopts a PHP database.
CREATE TABLE "activity_attempts" ("id" varchar not null, "workflow_run_id" varchar not null, "activity_execution_id" varchar not null, "workflow_task_id" varchar, "attempt_number" integer not null, "status" varchar not null, "lease_owner" varchar, "started_at" datetime not null, "last_heartbeat_at" datetime, "lease_expires_at" datetime, "closed_at" datetime, "created_at" datetime, "updated_at" datetime, "worker_attempt_id" varchar, primary key ("id"));
CREATE TABLE "activity_executions" ("id" varchar not null, "workflow_run_id" varchar not null, "sequence" integer not null, "activity_class" varchar not null, "activity_type" varchar not null, "status" varchar not null, "payload_codec" varchar, "arguments" text, "result" text, "exception" text, "connection" varchar, "queue" varchar, "attempt_count" integer not null default '1', "current_attempt_id" varchar, "retry_policy" text, "parallel_group_path" text, "activity_options" text, "schedule_deadline_at" datetime, "close_deadline_at" datetime, "schedule_to_close_deadline_at" datetime, "heartbeat_deadline_at" datetime, "started_at" datetime, "closed_at" datetime, "last_heartbeat_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "runtime_credentials" ("id" varchar not null, "name" varchar, "subject" varchar not null, "roles" text not null, "tenant" varchar not null, "claims" text, "token_prefix" varchar not null, "token_hash" varchar not null, "expires_at" datetime, "revoked_at" datetime, "rotated_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "runtime_external_payload_backup_hold" ("id" integer not null, "owner" varchar, "acquired_at" datetime, "expires_at" datetime, primary key ("id"));
CREATE TABLE "runtime_external_payload_cleanup_stats" ("namespace" varchar not null, "passes_total" integer not null default '0', "deleted_references_total" integer not null default '0', "deleted_backing_objects_total" integer not null default '0', "shared_objects_preserved_total" integer not null default '0', "blocked_outcomes_total" integer not null default '0', "storage_driver_failures_total" integer not null default '0', "last_processed" integer not null default '0', "last_deleted_references" integer not null default '0', "last_deleted_backing_objects" integer not null default '0', "last_shared_objects_preserved" integer not null default '0', "last_blocked_outcomes" integer not null default '0', "last_storage_driver_failures" integer not null default '0', "last_pass_status" varchar, "last_completed_at" datetime, "last_storage_failure_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("namespace"));
CREATE TABLE "runtime_external_payload_object_locks" ("bucket" integer not null, primary key ("bucket"));
CREATE TABLE "runtime_external_payloads" ("id" varchar not null, "namespace" varchar not null, "storage_uri" text not null, "storage_uri_sha256" varchar not null, "codec" varchar not null, "sha256" varchar not null, "size_bytes" integer not null, "retained_at" datetime, "expires_at" datetime, "last_fetched_at" datetime, "created_at" datetime, "updated_at" datetime, "upload_status" varchar not null default 'ready', primary key ("id"));
