CREATE TABLE "search_attribute_definitions" ("id" integer primary key autoincrement not null, "namespace" varchar not null, "name" varchar not null, "type" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "workflow_child_calls" ("id" integer primary key autoincrement not null, "parent_workflow_run_id" varchar not null, "parent_workflow_instance_id" varchar not null, "sequence" integer not null, "child_workflow_type" varchar not null, "child_workflow_class" varchar not null, "requested_child_id" varchar, "resolved_child_instance_id" varchar, "resolved_child_run_id" varchar, "parent_close_policy" varchar not null default 'abandon', "connection" varchar, "queue" varchar, "compatibility" varchar, "retry_policy" text, "timeout_policy" text, "cancellation_propagation" tinyint(1) not null default '0', "status" varchar not null default 'scheduled', "result_payload_reference" varchar, "failure_reference" varchar, "closed_reason" varchar, "scheduled_at" datetime not null, "started_at" datetime, "closed_at" datetime, "arguments" text, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("parent_workflow_run_id") references "workflow_runs"("id") on delete cascade);
CREATE TABLE "workflow_child_projection_repairs" ("workflow_history_event_id" varchar not null, "workflow_run_id" varchar not null, "workflow_task_id" varchar not null, "history_sequence" integer not null, "failure_id" varchar, "failed_child_counted_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("workflow_history_event_id"));
CREATE TABLE "workflow_commands" ("id" varchar not null, "workflow_instance_id" varchar, "workflow_run_id" varchar, "requested_workflow_run_id" varchar, "resolved_workflow_run_id" varchar, "command_type" varchar not null, "target_scope" varchar not null default 'instance', "source" varchar not null default 'php', "context" text, "request_id" varchar, "status" varchar not null, "outcome" varchar, "workflow_class" varchar, "workflow_type" varchar, "payload_codec" varchar, "payload" text, "rejection_reason" varchar, "command_sequence" integer, "message_sequence" integer, "accepted_at" datetime, "applied_at" datetime, "rejected_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "workflow_durable_stream_items" ("id" integer primary key autoincrement not null, "stream_id" integer not null, "namespace" varchar not null, "workflow_run_id" varchar not null, "stream_name" varchar not null, "offset" integer not null, "idempotency_key" varchar, "origin" varchar not null default 'workflow_command', "origin_reference" varchar, "payload" text, "payload_reference" varchar, "payload_codec" varchar, "item_type" varchar, "content_type" varchar, "emitted_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("stream_id") references "workflow_durable_streams"("id") on delete cascade);
CREATE TABLE "workflow_durable_streams" ("id" integer primary key autoincrement not null, "namespace" varchar not null, "workflow_instance_id" varchar not null, "workflow_run_id" varchar not null, "stream_name" varchar not null, "status" varchar not null default 'open', "last_offset" integer not null default '-1', "total_items" integer not null default '0', "retention_seconds" integer, "opened_at" datetime, "last_appended_at" datetime, "closed_at" datetime, "error_reason" varchar, "pending_items" integer not null default '0', "metadata" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "workflow_failures" ("id" varchar not null, "workflow_run_id" varchar not null, "source_kind" varchar not null, "source_id" varchar not null, "propagation_kind" varchar not null, "failure_category" varchar, "non_retryable" tinyint(1) not null default '0', "handled" tinyint(1) not null default '0', "exception_class" varchar not null, "message" text not null, "file" text not null, "line" integer, "trace_preview" text, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "workflow_history_events" ("id" varchar not null, "workflow_run_id" varchar not null, "sequence" integer not null, "event_type" varchar not null, "payload" text, "workflow_task_id" varchar, "workflow_command_id" varchar, "recorded_at" datetime, "created_at" datetime, "updated_at" datetime, "recorded_at_utc" datetime, primary key ("id"));
CREATE TABLE "workflow_inbound_stream_items" ("id" integer primary key autoincrement not null, "stream_id" integer not null, "namespace" varchar not null, "workflow_instance_id" varchar not null, "stream_name" varchar not null, "message_id" varchar not null, "position" integer not null, "payload_codec" varchar not null, "payload_blob" text not null, "payload_hash" varchar not null, "delivered_run_id" varchar, "workflow_command_id" varchar, "delivered_at" datetime, "consumed_run_id" varchar, "consumed_task_id" varchar, "consumed_at" datetime, "created_at" datetime, "updated_at" datetime, "payload_released_at" datetime, foreign key("stream_id") references "workflow_inbound_streams"("id") on delete cascade);
